{
  "packet_id": "H6-T01-2",
  "claim_id": "C020",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C020.component",
    "value": "Baseline and reduced configurations must use the same repetition rule, declared in advance.",
    "scope": "Repeated-test comparability; no particular repetition threshold is specified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P015 explicitly requires a shared, predeclared repetition rule for baseline and reduced configurations."
    }
  },
  "signal_basis": {
    "component_id": "C020.signal_basis",
    "value": "Reduction retains configurations that repeatedly reproduce failure; the informative pattern contrasts a repeatedly late reduced configuration with further removals that cease to reproduce lateness. A common predeclared repetition rule governs baseline and reduced tests, with inconsistent or otherwise uncertain outcomes classified as unresolved.",
    "scope": "Repeated reproduction judgments within the selected case's reduction tests.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the retention procedure, contrasting reproduction signal, and common evaluation rule, including unresolved outcomes."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C020.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is a supported procedural comparability requirement, not a warrant conditional on an unresolved empirical relation."
    }
  },
  "rationale": "The procedure compares repeated failure reproduction across configurations. Applying the same rule declared beforehand makes those judgments comparable under a fixed criterion. This licenses the stated procedural requirement without establishing any particular repetition threshold or statistical reliability.",
  "uncertainty": "The mapping leaves the repetition threshold unspecified; the claim expressly preserves that limit.",
  "anomalies": []
}
